package com.android.messaging.util;
import android.Manifest;import android.app.Notification;import android.app.NotificationChannel;import android.app.NotificationManager;import android.app.PendingIntent;import android.content.Context;import android.content.Intent;import android.media.AudioAttributes;import android.net.Uri;import android.os.Build;import android.content.pm.PackageManager;import com.android.messaging.R;import com.android.messaging.ui.conversation.ConversationActivity;import java.util.List;
public final class NotificationHelper {private static final String PRE="simplesms_";private NotificationHelper(){}
 public static void incoming(Context c,String a,long thread,String body){if(!AppPrefs.notifications(c)||AppPrefs.muted(c,a))return;if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(n==null)return;Uri sound=AppPrefs.tone(c,a);boolean vib=AppPrefs.vibrate(c);String ch=PRE+Integer.toHexString((a+"|"+sound+"|"+vib).hashCode());if(Build.VERSION.SDK_INT>=26){NotificationChannel x=new NotificationChannel(ch,"Messages from "+ContactResolver.name(c,a),NotificationManager.IMPORTANCE_DEFAULT);x.enableVibration(vib);x.setSound(sound,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build());x.setLockscreenVisibility(AppPrefs.preview(c)?Notification.VISIBILITY_PRIVATE:Notification.VISIBILITY_SECRET);n.createNotificationChannel(x);}Intent open=new Intent(c,ConversationActivity.class).putExtra(ConversationActivity.EXTRA_THREAD_ID,thread).putExtra(ConversationActivity.EXTRA_ADDRESS,a);PendingIntent pi=PendingIntent.getActivity(c,id(thread),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c);b.setSmallIcon(R.drawable.ic_notification).setContentTitle(ContactResolver.name(c,a)).setContentText(AppPrefs.preview(c)?body:"New message").setContentIntent(pi).setAutoCancel(true).setCategory(Notification.CATEGORY_MESSAGE).setVisibility(AppPrefs.preview(c)?Notification.VISIBILITY_PRIVATE:Notification.VISIBILITY_SECRET);if(Build.VERSION.SDK_INT<26){b.setSound(sound);if(vib)b.setVibrate(new long[]{0,180,120,180});}n.notify(id(thread),b.build());}
 public static void cancel(Context c,long thread){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(n!=null)n.cancel(id(thread));}
 public static void clearChannels(Context c){if(Build.VERSION.SDK_INT<26)return;NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(n==null)return;List<NotificationChannel>cs=n.getNotificationChannels();for(NotificationChannel x:cs)if(x.getId().startsWith(PRE))n.deleteNotificationChannel(x.getId());}
 private static int id(long t){return(int)((t^(t>>>32))&0x7fffffff);}}
